// Prints an env file with random, throwaway secrets for a CI test stack:
//   node tests/write-ci-env.js > ci.env
// Every build gets new values, and the stack (including its database volume) is
// deleted after the end-to-end test, so none of these values are ever reused.
const { randomBytes } = require('node:crypto');

const random = bytes => randomBytes(bytes).toString('hex');

const lines = [
  '# Generated by tests/write-ci-env.js for one CI build. Do not commit.',
  'POSTGRES_USER=ecommerce',
  `POSTGRES_PASSWORD=${random(16)}`,
  'POSTGRES_DB=ecommerce',
  `JWT_SECRET=${random(32)}`,
  `INTERNAL_SERVICE_TOKEN=${random(32)}`,
  // CI machines are often busy; give service-to-service calls more time than the 5 s default.
  'REQUEST_TIMEOUT_MS=15000',
  'ADMIN_EMAIL=ci-admin@example.com',
  `ADMIN_PASSWORD=Ci-${random(12)}`,
  // No spaces in values: the Jenkinsfile loads this file with the shell (". ./ci.env").
  'ADMIN_NAME=CI-Admin'
];

const unsafe = lines.filter(line => !line.startsWith('#') && /\s/.test(line));
if (unsafe.length) throw new Error(`ci.env values must not contain whitespace: ${unsafe.join(', ')}`);

process.stdout.write(lines.join('\n') + '\n');
